        :root {
            --primary-color: #2563eb;
            --primary-hover: #1d4ed8;
            --error-color: #dc2626;
            --text-color: #1f2937;
            --text-muted: #6b7280;
            --border-color: #d1d5db;
            --bg-color: #f3f4f6;
            --card-bg: #ffffff;
            --focus-ring: rgba(37, 99, 235, 0.4);
            --error-ring: rgba(220, 38, 38, 0.4);
        }

        * {
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            padding: 1.5rem;
            line-height: 1.5;
        }

        .contact-container {
            background: var(--card-bg);
            padding: 2.5rem;
            border-radius: 12px;
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
            width: 100%;
            max-width: 460px;
        }

        .contact-container h1 {
            margin-top: 0;
            margin-bottom: 1.5rem;
            font-size: 1.5rem;
            font-weight: 600;
        }

        .form-field {
            margin-bottom: 1.5rem;
            display: flex;
            flex-direction: column;
        }

        .form-field label {
            font-weight: 500;
            margin-bottom: 0.5rem;
            font-size: 0.95rem;
        }

        .required-marker {
            color: var(--error-color);
            margin-left: 0.2rem;
        }

        .form-field input {
            padding: 0.75rem 1rem;
            border: 1px solid var(--border-color);
            border-radius: 6px;
            font-size: 1rem;
            transition: border-color 0.2s, box-shadow 0.2s;
            font-family: inherit;
            width: 100%;
        }

        .form-field input:focus {
            outline: none;
            border-color: var(--primary-color);
            box-shadow: 0 0 0 3px var(--focus-ring);
        }

        .form-field input[aria-invalid="true"] {
            border-color: var(--error-color);
        }

        .form-field input[aria-invalid="true"]:focus {
            box-shadow: 0 0 0 3px var(--error-ring);
        }

        .help-text {
            margin: 0.4rem 0 0;
            font-size: 0.85rem;
            color: var(--text-muted);
        }

        .error-message {
            margin: 0.4rem 0 0;
            font-size: 0.85rem;
            color: var(--error-color);
            font-weight: 500;
        }

        .submit-button {
            width: 100%;
            background-color: var(--primary-color);
            color: white;
            border: none;
            padding: 0.875rem 1.5rem;
            border-radius: 6px;
            font-size: 1rem;
            font-weight: 500;
            cursor: pointer;
            transition: background-color 0.2s;
            margin-top: 0.5rem;
        }

        .submit-button:hover {
            background-color: var(--primary-hover);
        }

        .submit-button:focus {
            outline: none;
            box-shadow: 0 0 0 3px var(--focus-ring);
        }

        /* Screen reader only utility class */
        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            border: 0;
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef } = React;

        function ContactForm() {
            const [errors, setErrors] = useState({});
            const formRef = useRef(null);

            const handleSubmit = (e) => {
                e.preventDefault();
                const form = e.target;

                // Reset errors
                const newErrors = {};

                // Validate Full Name
                if (!form.name.value.trim()) {
                    newErrors.name = "Error: Full name is required.";
                }

                // Validate Email
                if (!form.email.value.trim()) {
                    newErrors.email = "Error: Email address is required.";
                } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email.value)) {
                    newErrors.email = "Error: Enter a valid email address like name@example.com.";
                }

                // Validate Phone (Optional, but if provided, must be somewhat valid)
                if (form.phone.value.trim() && !/^[\d\-\+\s\(\)]+$/.test(form.phone.value)) {
                    newErrors.phone = "Error: Enter a valid phone number (e.g. 555-123-4567).";
                }

                setErrors(newErrors);

                // Focus management for accessibility
                if (Object.keys(newErrors).length > 0) {
                    const firstInvalidId = Object.keys(newErrors)[0];
                    const element = document.getElementById(firstInvalidId);
                    if (element) {
                        element.focus();
                    }
                } else {
                    // Form is valid - handle submission here
                    alert("Support request submitted successfully!");
                    form.reset();
                    setErrors({});
                }
            };

            return (
                <main className="contact-container">
                    <h1>Contact Support</h1>
                    <form ref={formRef} noValidate onSubmit={handleSubmit}>

                        <div className="form-field">
                            <label htmlFor="name">
                                Full name <span aria-hidden="true" className="required-marker">*</span>
                            </label>
                            <input 
                                id="name" 
                                name="name" 
                                type="text" 
                                required 
                                autoComplete="name"
                                aria-invalid={!!errors.name}
                                aria-describedby={errors.name ? "name-error" : undefined}
                            />
                            {errors.name && <p id="name-error" className="error-message" role="alert">{errors.name}</p>}
                        </div>

                        <div className="form-field">
                            <label htmlFor="email">
                                Email address <span aria-hidden="true" className="required-marker">*</span>
                            </label>
                            <input 
                                id="email" 
                                name="email" 
                                type="email" 
                                required 
                                autoComplete="email"
                                aria-invalid={!!errors.email}
                                aria-describedby={errors.email ? "email-error" : undefined}
                            />
                            {errors.email && <p id="email-error" className="error-message" role="alert">{errors.email}</p>}
                        </div>

                        <div className="form-field">
                            <label htmlFor="phone">Phone number (optional)</label>
                            <input 
                                id="phone" 
                                name="phone" 
                                type="tel" 
                                autoComplete="tel"
                                aria-invalid={!!errors.phone}
                                aria-describedby={`phone-hint ${errors.phone ? "phone-error" : ""}`.trim()}
                            />
                            <p id="phone-hint" className="help-text">Format: e.g., 555-123-4567</p>
                            {errors.phone && <p id="phone-error" className="error-message" role="alert">{errors.phone}</p>}
                        </div>

                        <button type="submit" className="submit-button">Send message</button>
                    </form>
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ContactForm />);
    </script>
</body>
