 <body>
     <div id="root"></div>

     <script type="text/babel">
         const { useState, useRef } = React;

         function ContactForm() {
             const [errors, setErrors] = useState({});
             const formRef = useRef(null);

             const handleSubmit = (e) => {
                 e.preventDefault();
                 const form = e.target;

                 // Reset errors
                 const newErrors = {};

                 // Validate Full Name
                 if (!form.name.value.trim()) {
                     newErrors.name = "Error: Full name is required.";
                 }

                 // Validate Email
                 if (!form.email.value.trim()) {
                     newErrors.email = "Error: Email address is required.";
                 } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email.value)) {
                     newErrors.email = "Error: Enter a valid email address like name@example.com.";
                 }

                 // Validate Phone (Optional, but if provided, must be somewhat valid)
                 if (form.phone.value.trim() && !/^[\d\-\+\s\(\)]+$/.test(form.phone.value)) {
                     newErrors.phone = "Error: Enter a valid phone number (e.g. 555-123-4567).";
                 }

                 setErrors(newErrors);

                 // Focus management for accessibility
                 if (Object.keys(newErrors).length > 0) {
                     const firstInvalidId = Object.keys(newErrors)[0];
                     const element = document.getElementById(firstInvalidId);
                     if (element) {
                         element.focus();
                     }
                 } else {
                     // Form is valid - handle submission here
                     alert("Support request submitted successfully!");
                     form.reset();
                     setErrors({});
                 }
             };

             return (
                 <main className="contact-container">
                     <h1>Contact Support</h1>
                     <form ref={formRef} noValidate onSubmit={handleSubmit}>

                         <div className="form-field">
                             <label htmlFor="name">
                                 Full name <span aria-hidden="true" className="required-marker">*</span>
                             </label>
                             <input 
                                 id="name" 
                                 name="name" 
                                 type="text" 
                                 required 
                                 autoComplete="name"
                                 aria-invalid={!!errors.name}
                                 aria-describedby={errors.name ? "name-error" : undefined}
                             />
                             {errors.name && <p id="name-error" className="error-message" role="alert">{errors.name}</p>}
                         </div>

                         <div className="form-field">
                             <label htmlFor="email">
                                 Email address <span aria-hidden="true" className="required-marker">*</span>
                             </label>
                             <input 
                                 id="email" 
                                 name="email" 
                                 type="email" 
                                 required 
                                 autoComplete="email"
                                 aria-invalid={!!errors.email}
                                 aria-describedby={errors.email ? "email-error" : undefined}
                             />
                             {errors.email && <p id="email-error" className="error-message" role="alert">{errors.email}</p>}
                         </div>

                         <div className="form-field">
                             <label htmlFor="phone">Phone number (optional)</label>
                             <input 
                                 id="phone" 
                                 name="phone" 
                                 type="tel" 
                                 autoComplete="tel"
                                 aria-invalid={!!errors.phone}
                                 aria-describedby={`phone-hint ${errors.phone ? "phone-error" : ""}`.trim()}
                             />
                             <p id="phone-hint" className="help-text">Format: e.g., 555-123-4567</p>
                             {errors.phone && <p id="phone-error" className="error-message" role="alert">{errors.phone}</p>}
                         </div>

                         <button type="submit" className="submit-button">Send message</button>
                     </form>
                 </main>
             );
         }

         const root = ReactDOM.createRoot(document.getElementById('root'));
         root.render(<ContactForm />);
     </script>
 </body>
 </html>
